package main

import (
	"bufio"
	"fmt"
	"os"
	"strconv"
	"strings"
)

func main() {
	scanner := bufio.NewScanner(os.Stdin)
	scanner.Split(bufio.ScanLines)

	readLine := func() string {
		scanner.Scan()
		return scanner.Text()
	}

	readInts := func() []int {
		line := readLine()
		parts := strings.Fields(line)
		nums := make([]int, len(parts))
		for i, p := range parts {
			nums[i], _ = strconv.Atoi(p)
		}
		return nums
	}

	nStr := readLine()
	n, _ := strconv.Atoi(nStr)

	writer := bufio.NewWriter(os.Stdout)
	defer writer.Flush()

	for test := 0; test < n; test++ {
		f := readInts()
		s := readInts()

		result := 2
		if f[0] == 0 && f[1] == 0 && s[0] == 0 && s[1] == 0 {
			result = 0
		} else if f[0]+f[1]+s[0]+s[1] == 4 {
			result = 2
		} else {
			result = 1
		}

		fmt.Fprintln(writer, result)
	}
}

